Map<String,Object> values = new Map<String,Object>{ 'name' => 'Ada', 'count' => 2 };
System.assertEquals('Hello Ada: 2', 'Hello ${name}: ${count}'.template(values));
System.assertEquals('Escaped ${name} and Ada', 'Escaped $${name} and ${name}'.template(values));
Boolean missingTemplateValue = false;
try {
  'Hello ${missing}'.template(values);
} catch (StringException e) {
  missingTemplateValue = e.getMessage().contains('missing');
}
System.assert(missingTemplateValue);

